<script setup>
import { ref } from 'vue';
const settings=defineModel({type:Object,required:true});const selected=ref('');
function add(){const id=`custom_${Date.now().toString(36)}`;settings.value.providers.push({id,name:'自定义供应商',baseUrl:'',model:'',apiKey:'',hasApiKey:false,timeoutSeconds:120,maxOutputTokens:8192,jsonMode:true});selected.value=id;}
function remove(id){if(settings.value.providers.length===1)return;settings.value.providers=settings.value.providers.filter(item=>item.id!==id);if(settings.value.provider===id)settings.value.provider=settings.value.providers[0].id;selected.value='';}
</script>
<template><div class="provider-settings"><label class="form-label">默认供应商<select v-model="settings.provider" class="form-select"><option v-for="item in settings.providers" :key="item.id" :value="item.id">{{ item.name }} · {{ item.model }}</option></select></label><div class="provider-cards"><details v-for="item in settings.providers" :key="item.id" :open="selected===item.id" @toggle="$event.target.open&&(selected=item.id)"><summary><span><strong>{{ item.name }}</strong><small>{{ item.model || '填写模型名称' }}</small></span><span class="quiet-badge">{{ item.hasApiKey?'已配置密钥':'待配置' }}</span></summary><div class="provider-fields"><label>名称<input v-model="item.name" class="form-control" maxlength="80" required></label><label>基础地址<input v-model="item.baseUrl" class="form-control" type="url" placeholder="https://…/v1" required></label><label>模型名称<input v-model="item.model" class="form-control" required></label><label>API Key<input v-model="item.apiKey" class="form-control" type="password" autocomplete="new-password" :placeholder="item.hasApiKey?'留空保留当前密钥':'填写此供应商的密钥'"></label><div class="provider-number-fields"><label>超时 / 秒<input v-model.number="item.timeoutSeconds" class="form-control" type="number" min="10" max="240" required></label><label>输出 token 上限<input v-model.number="item.maxOutputTokens" class="form-control" type="number" min="512" max="32768" required></label></div><label class="checkbox-label caption"><input v-model="item.jsonMode" type="checkbox">使用 JSON 响应模式</label><button class="text-action" type="button" :disabled="settings.providers.length===1" @click="remove(item.id)">移除此供应商</button></div></details></div><button type="button" class="btn btn-outline-primary" @click="add">＋ 添加供应商</button><p class="caption muted mt-3">适用于 OpenAI 兼容接口。密钥仅保存在此工作空间，读取时不返回；修改地址需重新填写密钥。设置对新提交任务生效。</p></div></template>
